    Edge(int to, int rev, int flow, int capacity) : to(to), rev(rev), flow(flow), capacity(capacity) {}
};
vector<Edge> graph[MAXN];

void connect(int u, int v, int c, int rc = 0) {
    Edge e1(v, graph[v].size(), 0, c);
    Edge e2(u, graph[u].size(), 0, rc);
    graph[u].push_back(e1);
    graph[v].push_back(e2);
}

int dist[MAXN], ptr[MAXN], s, t;

bool levelGraph() {
    memset(dist, -1, sizeof(dist));
    dist[s] = 0;
    queue<int> q({s});
    while (!q.empty() && dist[t] == -1) {
        int u = q.front(); q.pop();
        for (auto &edge : graph[u]) {
            int v = edge.to;
            if (dist[v] == -1 && edge.flow < edge.capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[t] != -1;
}

int sendFlow(int u, int flow) {
    if (u == t || flow == 0)
        return flow;
