import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAXN = 300;
    static final int INF = (int)1e9;

    static class Edge {
        int to, rev, flow, capacity;
        Edge(int to, int rev, int flow, int capacity) {
            this.to = to;
            this.rev = rev;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static List<Edge>[] graph = new ArrayList[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }
    }

    static void connect(int u, int v, int c, int rc) {
        Edge e1 = new Edge(v, graph[v].size(), 0, c);
        Edge e2 = new Edge(u, graph[u].size(), 0, rc);
        graph[u].add(e1);
        graph[v].add(e2);
    }

    static int[] dist = new int[MAXN];
    static int[] ptr = new int[MAXN];
    static int s, t;

    static boolean levelGraph() {
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty() && dist[t] == -1) {
            int u = q.poll();
            for (Edge e : graph[u]) {
                int v = e.to;
                if (dist[v] == -1 && e.flow < e.capacity) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                }
            }
        }
        return dist[t] != -1;
    }

    static int sendFlow(int u, int flow) {
        if (u == t || flow == 0)
            return flow;
        for (; ptr[u] < graph[u].size(); ptr[u]++) {
            Edge e = graph[u].get(ptr[u]);
            int v = e.to;
            if (dist[v] != dist[u] + 1)
                continue;
            int pushed = sendFlow(v, Math.min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                graph[v].get(e.rev).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (levelGraph()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = sendFlow(s, Integer.MAX_VALUE)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int[] dx = {-1, 0, 0, 1};
    static int[] dy = {0, -1, 1, 0};

    static int n, m;
    static List<String> lab, rea;
    static int[][] obs, timeMap, distMap;

    static void computeDistances(int r, int c, int[][] dis, boolean check, int[][] timeMap, boolean[][] obs) {
        for (int i = 0; i < n; i++)
            Arrays.fill(dis[i], -1);
        dis[r][c] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{r, c});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pr = p[0], pc = p[1];
            if (check && dis[pr][pc] == timeMap[pr][pc])
                continue;
            for (int i = 0; i < 4; i++) {
                int nr = pr + dx[i];
                int nc = pc + dy[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || dis[nr][nc] != -1 || obs[nr][nc])
                    continue;
                if (check && timeMap[nr][nc] > -1 && dis[pr][pc] + 1 > timeMap[nr][nc])
                    continue;
                dis[nr][nc] = dis[pr][pc] + 1;
                q.offer(new int[]{nr, nc});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        lab = new ArrayList<>();
        rea = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            lab.add(br.readLine());
        }
        for (int i = 0; i < n; i++) {
            rea.add(br.readLine());
        }

        obs = new int[n][n];
        timeMap = new int[n][n];
        distMap = new int[n][n];

        boolean[][] obsBool = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                obs[i][j] = (lab.get(i).charAt(j) == 'Y');
                obsBool[i][j] = obs[i][j];
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (lab.get(i).charAt(j) == 'Z') {
                    computeDistances(i, j, timeMap, false, null, null);
                }
            }
        }

        s = 2 * n * n + 5;
        t = s + 1;

        for (int i = 0; i < MAXN; i++) {
            graph[i].clear();
        }

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                char cellChar = lab.get(x).charAt(y);
                if (cellChar == 'Z' || cellChar == 'Y')
                    continue;
                int capacity = cellChar - '0';

                connect(s, n * x + y, capacity, 0);
                connect(n * n + n * x + y, t, rea.get(x).charAt(y) - '0', 0);

                computeDistances(x, y, distMap, true, timeMap, obsBool);

                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (distMap[xp][yp] != -1 && distMap[xp][yp] <= m) {
                            connect(n * x + y, n * n + n * xp + yp, INF, 0);
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
    }
}
